"""Generate all 9 MIFECO pipeline flow SVGs."""

import os

OUT_DIR = os.path.expanduser("~/.hermes/pipeline-engine/dashboard/flows")

SVG_TEMPLATE = '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 650 50" width="100%" height="50">
  <defs>
    <style>
      .stage-box {{
        fill: #1a2332;
        stroke: #334155;
        stroke-width: 1.2;
        rx: 6;
      }}
      .stage-text {{
        fill: #e2e8f0;
        font-family: 'Inter', -apple-system, sans-serif;
        font-size: 11px;
        text-anchor: middle;
        dominant-baseline: central;
      }}
      .stage-active {{
        fill: #00ffcc22;
        stroke: #00ffcc;
        stroke-width: 1.5;
      }}
      .arrow-line {{
        stroke: #00ffcc;
        stroke-width: 1.5;
        fill: none;
      }}
      .arrow-head {{
        fill: #00ffcc;
      }}
    </style>
    <marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
      <path d="M0,0 L6,3 L0,6 Z" class="arrow-head"/>
    </marker>
  </defs>
  {arrows}
  {boxes}
  {labels}
</svg>
'''

STAGES = [6, 6, 6, 6, 6, 6, 6, 6, 6]  # all have 6 stages

PIPELINES = [
    # (filename, stages_list)
    ("lead-generation", ["Sources", "Capture", "Dedup", "Enrich", "Score", "Route"]),
    ("promotion-generation", ["Brief", "Creative", "Assets", "Copy", "Schedule", "Launch"]),
    ("book-ideation-writing", ["Concept", "Outline", "Draft", "Edit", "Beta", "Final"]),
    ("book-publishing", ["Format", "Cover", "KDP Pkg", "Upload", "Launch", "Monitor"]),
    ("saas-ideation-coding-testing", ["Idea", "Spec", "Prototype", "Code", "Test", "Review"]),
    ("saas-branding-hosting-deployment", ["Brand Kit", "Domain", "CI/CD", "Deploy", "Monitor", "Scale"]),
    ("saas-sales-management", ["Lead In", "Demo", "Proposal", "Negotiate", "Close", "Onboard"]),
    ("consulting-topic-ideation-writing", ["Research", "Outline", "Draft", "Review", "Design", "Publish"]),
    ("consulting-sales-deployment-report", ["Lead", "Assess", "Strategy", "Deploy", "Review", "Report"]),
]

BOX_W = 72
BOX_H = 28
BOX_Y = (50 - BOX_H) // 2  # 11
GAP = 34
LEFT = 25

def generate_svg(filename, stages):
    positions = []
    for i in range(6):
        x = LEFT + i * (BOX_W + GAP)
        positions.append(x)

    # Build arrow paths: from right edge of box i to left edge of box i+1
    arrows_svg = ""
    for i in range(5):
        x1 = positions[i] + BOX_W
        x2 = positions[i+1]
        y = BOX_Y + BOX_H // 2
        arrows_svg += f'    <line x1="{x1}" y1="{y}" x2="{x2}" y2="{y}" class="arrow-line" marker-end="url(#arrow)"/>\n'

    # Build stage boxes
    boxes_svg = ""
    labels_svg = ""
    for i, (x, label) in enumerate(zip(positions, stages)):
        cx = x + BOX_W // 2
        cy = BOX_Y + BOX_H // 2
        boxes_svg += f'    <rect x="{x}" y="{BOX_Y}" width="{BOX_W}" height="{BOX_H}" class="stage-box"/>\n'
        labels_svg += f'    <text x="{cx}" y="{cy}" class="stage-text">{label}</text>\n'

    svg_content = SVG_TEMPLATE.format(arrows=arrows_svg, boxes=boxes_svg, labels=labels_svg)

    filepath = os.path.join(OUT_DIR, f"{filename}.svg")
    with open(filepath, "w") as f:
        f.write(svg_content)
    print(f"  Created: {filepath} ({len(svg_content)} bytes)")
    return filepath

if __name__ == "__main__":
    print("Generating 9 MIFECO pipeline flow SVGs...")
    for name, stages in PIPELINES:
        generate_svg(name, stages)
    print("Done!")
"}

